export interface ApiResponse<TData = unknown, TMeta = Record<string, string>> {
  readonly success: boolean;
  readonly data?: TData;
  readonly error?: {
    code: number;
    message: string;
  };
}

impl<T> Deref for MutexGuard<'_, T> {
    type Target = T;
    fn deref(&self) -> &T {
        unsafe { &*self.lock.data.get() }
    }
}

inline uint32_t popcount_u32(uint32_t val) noexcept {
    return static_cast<uint32_t>(__builtin_popcount(val));
}
